const root = $json ?? {};
const message = root.messages?.[0]
  ?? root.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]
  ?? root.entry?.[0]?.changes?.[0]?.value?.messages?.[0]
  ?? null;
const contacts = root.contacts
  ?? root.body?.entry?.[0]?.changes?.[0]?.value?.contacts
  ?? root.entry?.[0]?.changes?.[0]?.value?.contacts
  ?? [];
const isTextMessage = message?.type === 'text' && typeof message?.text?.body === 'string';
return [{ json: {
  waMessageId: message?.id ?? null,
  phoneNumber: message?.from ?? null,
  messageType: message?.type ?? null,
  isTextMessage,
  messageText: isTextMessage ? message.text.body.trim() : '',
  messageTextForStorage: isTextMessage ? message.text.body : `[Non-text message received: ${message?.type ?? 'unknown'}]`,
  profileName: contacts?.[0]?.profile?.name ?? null
}}];

const DEFAULT_REPLY = "Sorry, I could not understand that. Could you rephrase your appointment request?";
const ALLOWED_INTENTS = ['BOOK', 'AVAILABILITY_CHECK', 'SPECIALIZATION_SEARCH', 'MISSING_INFO', 'UNSUPPORTED'];

function safeDefaults(replyText) {
  return {
    intent: 'UNSUPPORTED',
    doctor_name: null,
    specialization: null,
    requested_date: null,
    requested_start_time: null,
    requested_end_time: null,
    clarification_question: null,
    reply_text: replyText || DEFAULT_REPLY
  };
}

const raw = $input.first().json.output || $input.first().json.text || '';
let parsed;
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = safeDefaults();
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || !ALLOWED_INTENTS.includes(parsed.intent)) {
  parsed = safeDefaults(parsed && typeof parsed === 'object' ? parsed.reply_text : null);
}

// Ensure every expected key exists so downstream expressions never hit undefined.
const merged = Object.assign(safeDefaults(parsed.reply_text), parsed);
merged.intent = ALLOWED_INTENTS.includes(merged.intent) ? merged.intent : 'UNSUPPORTED';

return [{ json: merged }];

const row = $input.first()?.json ?? {};
const matchCount = Number(row.match_count ?? 0);
return [{ json: {
  matchCount: Number.isFinite(matchCount) ? matchCount : 0,
  doctor_id: row.doctor_id ?? null,
  doctor_name: row.doctor_name ?? null,
  specialization: row.specialization ?? null,
  google_calendar_id: row.google_calendar_id ?? null
}}];

