UPDATE appointments
SET status = 'CANCELLED', updated_at = NOW()
WHERE appointment_id = $1;

SELECT COALESCE(
  json_agg(
    json_build_object(
      'doctor_id', doctor_id,
      'doctor_name', doctor_name,
      'specialization', specialization
    ) ORDER BY doctor_name
  ) FILTER (WHERE doctor_id IS NOT NULL),
  '[]'::json
) AS doctors
FROM doctors
WHERE ($1::text IS NULL OR doctor_name ILIKE '%' || $1 || '%')
  AND ($2::text IS NULL OR specialization ILIKE '%' || $2 || '%');

