const row = $input.first()?.json ?? {};
let doctors = row.doctors ?? [];
if (typeof doctors === 'string') {
  try { doctors = JSON.parse(doctors); } catch { doctors = []; }
}
if (!Array.isArray(doctors) || doctors.length === 0) {
  return [{ json: { reply_text: "I couldn't find any doctors matching that specialization. Please confirm the specialization or doctor's name." } }];
}
const names = doctors.map(d => `Dr. ${d.doctor_name} (${d.specialization})`).join(', ');
return [{ json: { reply_text: `Doctors available: ${names}. If you'd like to book or check availability, send the doctor or specialization, date, and time.` } }];

